			}
		}

		// All attributes were found on the resource: group the entire resource subtree under a single key.
		if len(afterResource) == 0 {
			newMD := pmetric.NewMetrics()
			rmClone := newMD.ResourceMetrics().AppendEmpty()
			rm.CopyTo(rmClone)
			mergeMetricsToResults(results, resourceKey.String(), newMD)
			continue
		}

		for j := 0; j < rm.ScopeMetrics().Len(); j++ {
			sm := rm.ScopeMetrics().At(j)

			// Resolve the remaining attributes at the scope level.
			var scopeKey strings.Builder
			var afterScope []string
			for _, a := range afterResource {
				if v, ok := sm.Scope().Attributes().Get(a); ok {
					scopeKey.WriteString(v.AsString())
				} else {
					afterScope = append(afterScope, a)
				}
			}

			prefix := resourceKey.String() + scopeKey.String()

			// All remaining attributes were found on the scope: group the entire scope subtree under a single key.
			if len(afterScope) == 0 {
				newMD := pmetric.NewMetrics()
				rmClone := newMD.ResourceMetrics().AppendEmpty()
