// attributesKey concatenates the string values of the given attribute keys, in order, that are present in the
// provided attribute map. Missing attributes contribute nothing to the key.
func attributesKey(attributes pcommon.Map, attrs []string) string {
	var key strings.Builder
	for _, a := range attrs {
		if v, ok := attributes.Get(a); ok {
			key.WriteString(v.AsString())
		}
	}
	return key.String()
}

// mergeMetricsToResults merges md into the batch stored under key, creating it if necessary.
func mergeMetricsToResults(results map[string]pmetric.Metrics, key string, md pmetric.Metrics) {
	if existing, ok := results[key]; ok {
		metrics.Merge(existing, md)
	} else {
		results[key] = md
	}
}

