// writeMetricsMap writes a map[string]pmetric.Metrics to path in the same YAML format that loadMetricsMap reads.
func writeMetricsMap(t *testing.T, path string, m map[string]pmetric.Metrics) {
	out := map[string]any{}
	marshaler := &pmetric.JSONMarshaler{}
	for key, md := range m {
		golden.NormalizeTimestamps := struct{}{} // placeholder to avoid unused import; removed below
		_ = golden.NormalizeTimestamps
		b, err := marshaler.MarshalMetrics(md)
		require.NoError(t, err)
		var generic map[string]any
		require.NoError(t, json2.Unmarshal(b, &generic))
		out[key] = generic
	}
	buf := &bytes.Buffer{}
	enc := yaml.NewEncoder(buf)
	enc.SetIndent(2)
	require.NoError(t, enc.Encode(out))
	require.NoError(t, os.WriteFile(path, buf.Bytes(), 0o600))
}

func sumMetric(sm pmetric.ScopeMetrics, name string, dps []struct {
	dpKey string
	val   float64
	ts    int
}) {
	m := sm.Metrics().AppendEmpty()
	m.SetName(name)
	sum := m.SetEmptySum()
	sum.SetAggregationTemporality(pmetric.AggregationTemporalityCumulative)
	sum.SetIsMonotonic(true)
	for _, d := range dps {
		dp := sum.DataPoints().AppendEmpty()
		dp.SetDoubleValue(d.val)
		dp.SetTimestamp(pmetric.Timestamp(d.ts))
		if d.dpKey != "" {
			dp.Attributes().PutStr("datapoint_key", d.dpKey)
		}
	}
}

